package com.retro.launcher;
import android.app.*;
import android.content.*;
import android.widget.*;
import android.view.*;
import org.json.*;
import java.net.*;
import java.io.*;

final class Features {
 final MainActivity a; AlertDialog dialog; volatile boolean busy; String status=""; long lastAttempt;
 Features(MainActivity activity){a=activity;}
 void show(AlertDialog d){if(dialog!=null)dialog.dismiss();dialog=d;d.setOnDismissListener(x->{if(dialog==d)dialog=null;});d.show();}
 boolean key(int key){if(dialog==null)return false;if(!dialog.isShowing()){dialog=null;return false;}int mapped=key==android.view.KeyEvent.KEYCODE_F12?4:23;if(mapped==4)dialog.dismiss();else {dialog.dispatchKeyEvent(new KeyEvent(0,mapped));dialog.dispatchKeyEvent(new KeyEvent(1,mapped));}return true;}
 void choose(String title,String[] values,int selected,java.util.function.IntConsumer action){AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setSingleChoiceItems(values,selected,(which,n)->{which.dismiss();action.accept(n);a.view.invalidate();}).setNegativeButton("Back",null).create();show(d);}
 void appearance(){final String[] labels={"Chrome Blue","Amethyst","Silver"},names={"chrome_blue","violet","silver"};AlertDialog d=new AlertDialog.Builder(a).setTitle("Color theme").setAdapter(new android.widget.ArrayAdapter<String>(a,android.R.layout.simple_list_item_1,labels){public android.view.View getView(int position,android.view.View convert,android.view.ViewGroup parent){android.widget.TextView v=(android.widget.TextView)super.getView(position,convert,parent);android.graphics.Bitmap b=a.pack.get("ui/theme_swatch_"+names[position]+".png");if(b!=null){android.graphics.drawable.BitmapDrawable icon=new android.graphics.drawable.BitmapDrawable(a.getResources(),b);int size=(int)(40*a.getResources().getDisplayMetrics().density);icon.setBounds(0,0,size,size);v.setCompoundDrawables(icon,null,null,null);v.setCompoundDrawablePadding(12);}return v;}},(which,n)->{a.prefs.edit().putInt("theme",n).apply();a.view.invalidate();}).setNegativeButton("Back",null).create();show(d);}

 void wallpaper(){choose("Wallpaper",new String[]{"Midnight gradient","Orbit lines","Plain dark","Night Orbit (asset pack)"},a.prefs.getInt("wallpaper",3),n->a.prefs.edit().putInt("wallpaper",n).apply());}
 void launcherOptions(){show(new AlertDialog.Builder(a).setTitle("Options").setItems(new String[]{"Launcher settings","Phone settings","Home screen"},(d,n)->{if(n==0)a.page("Settings");if(n==1)a.system(android.provider.Settings.ACTION_SETTINGS);if(n==2)a.page("Home");}).setNegativeButton("Close",null).create());}
 void openApps(){if(KeyAccess.current!=null){if(!KeyAccess.current.performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_RECENTS))toast("App switcher unavailable on this firmware");}else show(new AlertDialog.Builder(a).setTitle("Open apps").setMessage("Enable Retro Orbit F1 key in Accessibility settings to open the phone’s app switcher. You can then switch apps and use the system’s close controls.").setPositiveButton("Set up",(d,n)->a.system(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)).setNegativeButton("Back",null).create());}
 void weatherMenu(){String cached=a.prefs.getString("weather_city","");show(new AlertDialog.Builder(a).setTitle("Weather"+(cached.isEmpty()?"":" • "+cached)).setItems(new String[]{"Choose city","Units: "+(a.prefs.getBoolean("fahrenheit",true)?"Fahrenheit":"Celsius"),"Refresh now","Disable weather","Data and attribution"},(d,n)->{if(n==0)city();if(n==1){a.prefs.edit().putBoolean("fahrenheit",!a.prefs.getBoolean("fahrenheit",true)).apply();a.view.invalidate();}if(n==2)refresh(true);if(n==3){a.prefs.edit().remove("weather_city").remove("weather_time").remove("weather_temp").apply();a.view.invalidate();}if(n==4)show(new AlertDialog.Builder(a).setTitle("Weather data").setMessage("Weather data by Open-Meteo.com (CC BY 4.0). Location search by GeoNames. Your chosen city is sent to Open-Meteo; no GPS is used. Free endpoint for non-commercial use. Updates at most hourly while launcher is open; cached data remains available offline.").setPositiveButton("Open source",(x,w)->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://open-meteo.com/")))).setNegativeButton("Back",null).create());}).setNegativeButton("Back",null).create());}
 void city(){EditText input=new EditText(a);input.setSingleLine();input.setHint("City or postal code");input.setText(a.prefs.getString("weather_city",""));show(new AlertDialog.Builder(a).setTitle("Weather location").setView(input).setPositiveButton("Search",(d,w)->search(input.getText().toString().trim())).setNegativeButton("Back",null).create());input.requestFocus();}
 void search(String query){if(query.length()<2){toast("Enter at least two characters");return;}if(busy){toast("Please wait for weather request");return;}busy=true;status="Searching…";new Thread(()->{try{JSONArray result=json("https://geocoding-api.open-meteo.com/v1/search?count=5&name="+URLEncoder.encode(query,"UTF-8")).optJSONArray("results");if(result==null||result.length()==0)throw new IOException("No matching cities");String[] names=new String[result.length()];for(int i=0;i<names.length;i++){JSONObject o=result.getJSONObject(i);names[i]=o.getString("name")+", "+o.optString("admin1")+", "+o.optString("country_code");}busy=false;a.runOnUiThread(()->{if(a.isDestroyed())return;choose("Choose location",names,-1,n->{try{JSONObject o=result.getJSONObject(n);a.prefs.edit().putString("weather_city",o.getString("name")).putString("weather_lat",o.getString("latitude")).putString("weather_lon",o.getString("longitude")).remove("weather_time").remove("weather_temp").apply();refresh(true);}catch(Exception e){toast("Location unavailable");}});});}catch(Exception e){a.runOnUiThread(()->toast("City search failed. Check connection or spelling."));}finally{busy=false;status="";}},"city-search").start();}
 static JSONObject json(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>1000000)throw new IOException("Oversized response");}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 void refresh(boolean force){if(busy||!a.prefs.contains("weather_city"))return;long now=System.currentTimeMillis();if(!force&&(now-a.prefs.getLong("weather_time",0)<3600000||now-lastAttempt<900000))return;lastAttempt=now;busy=true;String lat=a.prefs.getString("weather_lat","0"),lon=a.prefs.getString("weather_lon","0"),city=a.prefs.getString("weather_city","");status="Updating…";a.view.invalidate();new Thread(()->{try{JSONObject current=json("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code").getJSONObject("current");if(city.equals(a.prefs.getString("weather_city","")))a.prefs.edit().putFloat("weather_temp",(float)current.getDouble("temperature_2m")).putInt("weather_code",current.getInt("weather_code")).putLong("weather_time",System.currentTimeMillis()).apply();status="";}catch(Exception e){status="Offline / unavailable";}finally{busy=false;a.runOnUiThread(()->{if(!a.isDestroyed())a.view.invalidate();});}},"weather-refresh").start();}
 String temperature(){if(!a.prefs.contains("weather_temp"))return busy?"Updating…":a.prefs.contains("weather_city")?"--°":"Choose city";float c=a.prefs.getFloat("weather_temp",0);return Math.round(a.prefs.getBoolean("fahrenheit",true)?c*9/5+32:c)+"°"+(a.prefs.getBoolean("fahrenheit",true)?"F":"C");}
 String condition(){int code=a.prefs.getInt("weather_code",-1);if(code==0)return "Clear";if(code<=3&&code>=0)return "Cloudy";if(code==45||code==48)return "Fog";if(code>=95)return "Thunderstorms";if((code>=71&&code<=77)||code==85||code==86)return "Snow";if(code>=51)return "Rain";return "Unavailable";}
 String freshness(){long t=a.prefs.getLong("weather_time",0);if(t==0)return status.isEmpty()?"Not configured":status;if(System.currentTimeMillis()-t>7200000)return "Stale • "+new java.text.SimpleDateFormat("HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(t));return condition();}
 void appOptions(){if(a.apps.isEmpty())return;MainActivity.App app=a.apps.get(a.index);boolean favorite=a.favorites.contains(app);show(new AlertDialog.Builder(a).setTitle(app.label).setItems(new String[]{"Open",favorite?"Remove from wheel":"Add to wheel","App information","Reorder wheel","Choose icon"},(d,n)->{if(n==0)a.launch(app);if(n==1){if(favorite)a.favorites.remove(app);else a.favorites.add(app);a.save();a.view.invalidate();}if(n==2)a.startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+ComponentName.unflattenFromString(app.id).getPackageName())));if(n==3)a.page("Order");if(n==4)choose("App icon",new String[]{"Automatic","Original","Phone","Messages","Contacts","Camera","Music","Gallery","Browser","Calendar","Settings"},-1,i->{String[] keys={"","original","phone","messages","contacts","camera","music","gallery","browser","calendar","settings"};a.prefs.edit().putString("icon:"+app.id,keys[i]).apply();});}).setNegativeButton("Back",null).create());}
 void alertOptions(){android.service.notification.StatusBarNotification[] items=a.shownAlerts;if(a.index>=items.length)return;android.service.notification.StatusBarNotification item=items[a.index];show(new AlertDialog.Builder(a).setTitle("Notification").setItems(new String[]{"Open","Dismiss","Access settings"},(d,n)->{if(n==0)a.activate();if(n==1&&Alerts.current!=null){if(item.isClearable())Alerts.current.cancelNotification(item.getKey());else toast("This alert cannot be dismissed");}if(n==2)a.system("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS");}).setNegativeButton("Back",null).create());}
 void toast(String s){Toast.makeText(a,s,Toast.LENGTH_LONG).show();}
}
